// Stand-in for @supabase/ssr in the eval: hands back what it was given, so
// the hidden suite can read the cookie methods.
export function createServerClient(supabaseUrl, supabaseKey, options) {
  return { supabaseUrl, supabaseKey, options };
}

export function createBrowserClient(supabaseUrl, supabaseKey) {
  return { supabaseUrl, supabaseKey };
}
